def _publisher_for(Publisher, value):
    """The Publisher a stored text value means: an exact name match, else
    one whose name ends in "(<value>)" (so "SPC" -> "The Pacific Community
    (SPC)"), else a new publisher with that name."""
    return (
        Publisher.objects.filter(publisher_value=value).first()
        or Publisher.objects.filter(publisher_value__endswith=f"({value})").first()
        or Publisher.objects.create(publisher_value=value)
    )


